const items = $input.all();
const hire = items[0].json;

const name = hire.name || 'New Team Member';
const role = hire.role || 'Team Member';
const team = hire.team || 'Engineering';
const startDate = hire.startDate || new Date().toISOString().split('T')[0];
const buddyId = hire.buddyId || '';
const funFact = hire.funFact || '';
const email = hire.email || '';

const welcomeMsg = `:tada: *Welcome to the team, ${name}!* :tada:\n\n` +
  `:briefcase: *Role:* ${role}\n` +
  `:busts_in_silhouette: *Team:* ${team}\n` +
  `:calendar: *Start Date:* ${startDate}\n` +
  (funFact ? `\n:star2: *Fun Fact:* ${funFact}\n` : '') +
  `\nPlease give ${name} a warm welcome! :wave:`;

return [{json: {name, role, team, startDate, buddyId, email, welcomeMsg}}];
